BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP106-1-23','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。衛生福利部處務規程第8條第4款規定社會救助及社工司掌理急難救助與公益勸募政策之規劃、推動及相關法規之研擬，勸募活動財物使用計畫書屬公益勸募業務，官方答案C。公益勸募條例第4條（2020-01-15 修正）規定中央主管機關為衛生福利部。衛生福利部處務規程第8條自 2013-07-21 訂定發布後未曾修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0010053'),('SW-104-1-34','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。社會工作師法第17條規定社會工作師之行為必須遵守社會工作倫理守則，倫理守則由全國社會工作師公會聯合會訂定，報請中央主管機關備查。考試時適用之社會工作倫理守則（2008-03-28 內政部同意核備）第一章四規定社會工作倫理原則為尊重、關懷、正義、堅毅、廉潔、守法、專業，「服務」不在其中，官方答案D。現行條文（2018-12-15 修訂、2019-04-26 衛生福利部核備之社會工作師倫理守則）第一章四之倫理原則改為促進服務對象的最佳福祉、實踐弱勢優先及服務對象最佳利益、尊重服務對象的個別性及價值等6項敘述，已不再列關懷、守法等原則，依現行條文選項B、C亦非倫理原則，本題答案以考試時版本為準。依據：法務部全國法規資料庫（社會工作師法）、新北市政府社會局網站公布之社會工作倫理守則（2008-03-28 內政部同意核備版本）及衛生福利部網站公布之社會工作師倫理守則（2019-04-26 衛生福利部核備版本）（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SW-104-2-26','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-07-25。依社會工作師法第17條訂定之社會工作倫理守則，考試時版本（2008-03-28 內政部同意核備）第二章四「社會工作師作為專業人員的倫理責任」列有提升社會工作專業知能（4.1）、包容多元文化、尊重多元社會現象（4.2）、嚴禁參與違法之活動（4.3）；「尊重同僚之專業知識」屬第二章二「對同僚的倫理守則」（2.3），官方答案B。現行條文（2019-04-26 衛生福利部核備之社會工作師倫理守則）第二章四「對社會工作師專業的倫理責任」已刪除「嚴禁參與違法之活動」，依現行條文選項C亦不在該章，本題答案以考試時版本為準。依據：法務部全國法規資料庫（社會工作師法）、新北市政府社會局網站公布之社會工作倫理守則（2008-03-28 內政部同意核備版本）及衛生福利部網站公布之社會工作師倫理守則（2019-04-26 衛生福利部核備版本）（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SW-105-2-36','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-07-23。題目指定 2008-03-28 內政部同意核備之社會工作倫理守則（依社會工作師法第17條訂定），其第一章四列社會工作倫理原則為尊重、關懷、正義、堅毅、廉潔、守法、專業，尊重案主自我決定列於第一章五之倫理衝突處理原則，「自決」不在倫理原則之列，官方答案A。現行條文（2019-04-26 衛生福利部核備之社會工作師倫理守則）第一章四之倫理原則改為6項敘述，已不再列正義、守法等原則，依現行條文選項C、D亦不屬倫理原則，本題答案以考試時版本為準。依據：法務部全國法規資料庫（社會工作師法）、新北市政府社會局網站公布之社會工作倫理守則（2008-03-28 內政部同意核備版本）及衛生福利部網站公布之社會工作師倫理守則（2019-04-26 衛生福利部核備版本）（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SW-107-1-19','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。社會工作師法第17條規定倫理守則由全國社會工作師公會聯合會訂定，並非臺灣社會工作專業人員協會（選項A錯誤）。考試時適用之社會工作倫理守則（2008-03-28 內政部同意核備）與現行社會工作師倫理守則（2019-04-26 衛生福利部核備）均規定：隱私權為案主（服務對象）所有，其有權親自或透過監護人或法律代表決定放棄時，保密受到限制（第二章1.6 a，選項B正確）；面對倫理衝突時應以保護生命為最優先考量原則（第一章五，選項C錯誤）；案主（服務對象）縱已死亡，仍須重視其隱私權利（第二章1.6，選項D錯誤）。社會工作師法第17條自 2008-01-16 修正後未再修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫（社會工作師法）、新北市政府社會局網站公布之社會工作倫理守則（2008-03-28 內政部同意核備版本）及衛生福利部網站公布之社會工作師倫理守則（2019-04-26 衛生福利部核備版本）（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SW-108-1-23','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-01-19。考試時適用之社會工作倫理守則依社會工作師法第17條訂定，2006-12-22 經全國聯合會會員代表大會通過、2008-03-28 內政部同意核備（敘述①②正確）；該版本第一章一定義案主為接受社會工作服務的個人、家庭、團體或社區（敘述③漏列社區，錯誤）；第三章附則規定違反守則者由所屬社會工作師公會審議、處置（敘述④錯誤）。現行社會工作師倫理守則於 2018-12-15 修訂、2019-04-26 衛生福利部核備，文件首列 97 年 3 月 28 日內政部核備之沿革，改以「服務對象」稱之而不再定義案主，附則仍規定由公會審議、處置。社會工作師法第17條自 2008-01-16 修正後未再修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫（社會工作師法）、新北市政府社會局網站公布之社會工作倫理守則（2008-03-28 內政部同意核備版本）及衛生福利部網站公布之社會工作師倫理守則（2019-04-26 衛生福利部核備版本）（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SW-108-2-25','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-07-27。依社會工作師法第17條訂定之倫理守則，題目所稱第二版（2008-03-28 內政部同意核備）與考試時已施行之現行社會工作師倫理守則（2019-04-26 衛生福利部核備），其第二章對案主（服務對象）之倫理守則均規定：尊重並促進自我決定權（1.2）、維持正常專業關係（1.4）、保守業務秘密且縱已死亡仍須重視其隱私權利（1.6）、收取服務費用時應事先告知收費標準（1.7）；「提供服務後才告知需要收取服務費用」違反1.7，官方答案C。社會工作師法第17條自 2008-01-16 修正後未再修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫（社會工作師法）、新北市政府社會局網站公布之社會工作倫理守則（2008-03-28 內政部同意核備版本）及衛生福利部網站公布之社會工作師倫理守則（2019-04-26 衛生福利部核備版本）（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SW-112-1-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2023-02-18。依全民健康保險法第41條，醫療服務給付項目及支付標準由保險人與相關機關等代表共同擬訂，報主管機關核定發布；本題考該標準精神醫療治療費之申報規範。衛生福利部 2026-07-28 修正發布、2026-08-01 生效之精神疾病嚴重病人強制處置費用支付作業要點附表，其家族治療（60分鐘）項目（E45082）仍載明「限精神科醫師或精神科社工師(員)申報，並需附精神科專科醫師之醫囑及簽名」，行為治療計畫限精神專科、復健專科醫師或臨床心理師執行，選項B家族治療之申報規定未變。全民健康保險法第41條自 2011-01-26 修正後未再修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫（全民健康保險法）及衛生福利部中央健康保險署網站公布之精神疾病嚴重病人強制處置費用支付作業要點（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0060001');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>8 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>8 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-26T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-26T12:00:00+00:00'::timestamptz) IS DISTINCT FROM '6e4e49c48a273bd6642a37204030e6ac' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-26T12:00:00+00:00'::timestamptz AND q.legal_status=b.status AND q.legal_note=b.note AND q.legal_source_url=b.url)<>8 THEN RAISE EXCEPTION 'postimage count'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_5, count(*) FILTER (WHERE q.legal_status='changed') changed_3, count(*) total_8 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
